// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        uint256 before = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint256 after_ = c.proposalCount();
        assertTrue(after_ == before + 1, "each newGrantProposal must increment proposalCount by exactly 1");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function runTest(address _vader, address _usdv, address _vault) public {
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader);
    }
}

